import type http from "node:http";
import { handleChatStream } from "@mastra/ai-sdk";
import { toAISdkMessages } from "@mastra/ai-sdk/ui";
import { createUIMessageStreamResponse, type UIMessage } from "ai";
import { canUseAgent } from "./auth/access";
import type { SessionUser } from "./auth/session";
import { mastra } from "./mastra";

const MAX_BODY_BYTES = 1024 * 1024;

export type AgentSummary = { key: string; id: string; name: string; description: string };

/** Without a user, returns every agent; with one, only the agents that user may use. */
export function listAgents(user?: SessionUser): AgentSummary[] {
  return Object.entries(mastra.listAgents())
    .map(([key, agent]) => ({
      key,
      id: agent.id,
      name: agent.name,
      description: agent.getDescription(),
    }))
    .filter((agent) => !user || canUseAgent(user, agent.id));
}

/** Accepts either the Mastra registry key ("cfoAgent") or the agent id ("cfo"). */
function resolveAgentId(keyOrId: string): string | undefined {
  return listAgents().find((agent) => agent.key === keyOrId || agent.id === keyOrId)?.id;
}

/** One persisted chat per user per agent. */
export function chatThreadId(userId: string, agentId: string): string {
  return `${userId}:${agentId}`;
}

/** POST /api/chat/:agentId — streams an AI SDK v7 UI message stream (SSE). */
export async function handleChat(
  agentKeyOrId: string,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  user: SessionUser,
): Promise<void> {
  if (req.method !== "POST") {
    res.writeHead(405, { allow: "POST" }).end();
    return;
  }
  const agentId = resolveAgentId(agentKeyOrId);
  if (!agentId) {
    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
    return;
  }
  if (!canUseAgent(user, agentId)) {
    sendJson(res, 403, { error: "Forbidden" });
    return;
  }

  // Memory already holds the history, so only the newest (user) message is taken from the body.
  let message: UIMessage;
  try {
    const body = JSON.parse(await readBody(req)) as { messages?: unknown; message?: unknown };
    const last = (Array.isArray(body?.messages) ? body.messages.at(-1) : body?.message) as UIMessage | undefined;
    if (!last || last.role !== "user" || typeof last.id !== "string") throw new Error("user message required");
    // Namespace the id by user: storage upserts by message id, so a client-chosen id must not hit another user's rows.
    message = { ...last, id: `${user.id}:${last.id}` };
  } catch (error) {
    const tooLarge = error instanceof BodyTooLargeError;
    sendJson(res, tooLarge ? 413 : 400, {
      error: tooLarge ? "Request body too large" : "Expected JSON body whose last message has role \"user\"",
    });
    return;
  }

  // Stop generation when the browser disconnects.
  const abort = new AbortController();
  res.on("close", () => {
    if (!res.writableFinished) abort.abort();
  });

  // Only the user message is taken from the client: other AgentExecutionOptions (instructions,
  // maxSteps, tools...) must not be client-controlled. Memory thread and resource always come
  // from the session, never from the client.
  const stream = await handleChatStream({
    mastra,
    agentId,
    version: "v7",
    params: {
      messages: [message],
      memory: { thread: chatThreadId(user.id, agentId), resource: user.id },
      abortSignal: abort.signal,
    },
    onError: (error) => {
      console.error("Web chat stream failed", { agentId, error });
      return "Sorry, something went wrong while generating a reply.";
    },
  });
  const response = createUIMessageStreamResponse({ stream });

  res.writeHead(response.status, Object.fromEntries(response.headers));
  res.flushHeaders();
  if (!response.body) {
    res.end();
    return;
  }
  try {
    for await (const chunk of response.body) {
      if (abort.signal.aborted) break;
      res.write(chunk);
    }
  } finally {
    res.end();
  }
}

/** GET/DELETE /api/chat/:agentId/history — read or clear the caller's own chat with one agent. */
export async function handleChatHistory(
  agentKeyOrId: string,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  user: SessionUser,
): Promise<void> {
  if (req.method !== "GET" && req.method !== "DELETE") {
    res.writeHead(405, { allow: "GET, DELETE" }).end();
    return;
  }
  const agentId = resolveAgentId(agentKeyOrId);
  if (!agentId) {
    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
    return;
  }
  if (!canUseAgent(user, agentId)) {
    sendJson(res, 403, { error: "Forbidden" });
    return;
  }

  // The thread id embeds the user id and the resource id is checked, so only the caller's own chat is reachable.
  const agent = Object.values(mastra.listAgents()).find((a) => a.id === agentId);
  const memory = await agent?.getMemory();
  const threadId = chatThreadId(user.id, agentId);
  const thread = memory ? await memory.getThreadById({ threadId }) : null;
  const owned = thread?.resourceId === user.id;

  if (req.method === "DELETE") {
    if (memory && owned) await memory.deleteThread(threadId);
    res.writeHead(204).end();
    return;
  }
  if (!memory || !owned) {
    sendJson(res, 200, { messages: [] });
    return;
  }
  const { messages } = await memory.recall({ threadId, resourceId: user.id, perPage: false });
  sendJson(res, 200, { messages: toAISdkMessages(messages, { version: "v7" }) });
}

export function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

class BodyTooLargeError extends Error {}

async function readBody(req: http.IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += (chunk as Buffer).length;
    if (size > MAX_BODY_BYTES) throw new BodyTooLargeError();
    chunks.push(chunk as Buffer);
  }
  return Buffer.concat(chunks).toString("utf8");
}
import { useChat } from "@ai-sdk/react";
import type { ChatStatus, UIMessage } from "ai";
import { useSyncExternalStore } from "react";
import {
  chatsVersion,
  dismissHistoryError,
  getChat,
  historyError,
  isHistoryLoading,
  isUnread,
  retryHistory,
  subscribeChats,
} from "@/lib/chats";

export type AgentChat = {
  messages: UIMessage[];
  status: ChatStatus;
  /** True while a request is submitted or a reply is streaming. */
  running: boolean;
  /** True while the saved conversation is being fetched; sending is disabled until then. */
  loading: boolean;
  error: Error | undefined;
  send: (text: string) => void;
  stop: () => void;
  clear: () => void;
  retry: () => void;
  dismissError: () => void;
};

export function isRunning(status: ChatStatus): boolean {
  return status === "submitted" || status === "streaming";
}

/** The open agent's chat, streamed from POST /api/chat/:agentKey. */
export function useAgentChat(agentKey: string): AgentChat {
  const chat = getChat(agentKey);
  const helpers = useChat({ chat, throttle: 50 });
  useSyncExternalStore(subscribeChats, chatsVersion);
  const loading = isHistoryLoading(agentKey);
  const loadError = historyError(agentKey);
  return {
    messages: helpers.messages,
    status: helpers.status,
    running: isRunning(helpers.status),
    loading,
    error: helpers.error ?? loadError,
    send: (text) => {
      const trimmed = text.trim();
      if (!trimmed || isRunning(chat.status) || isHistoryLoading(agentKey)) return;
      void helpers.sendMessage({ text: trimmed });
    },
    stop: () => void helpers.stop(),
    clear: () => {
      void helpers.stop();
      helpers.clearError();
      helpers.setMessages([]);
    },
    retry: () => {
      if (loadError) return retryHistory(agentKey);
      helpers.clearError();
      void helpers.regenerate();
    },
    dismissError: () => {
      helpers.clearError();
      dismissHistoryError(agentKey);
    },
  };
}

export type AgentRowState = { messages: UIMessage[]; running: boolean; unread: boolean; error: boolean };

/** Sidebar summary for every agent, read from the per-agent Chat instances. */
export function useAgentChatSummaries(keys: string[]): Record<string, AgentRowState> {
  useSyncExternalStore(subscribeChats, chatsVersion);
  return Object.fromEntries(
    keys.map((key) => {
      const chat = getChat(key);
      return [
        key,
        { messages: chat.messages, running: isRunning(chat.status), unread: isUnread(key), error: chat.status === "error" },
      ];
    }),
  );
}
import { getToolName, isDataUIPart, isReasoningUIPart, isTextUIPart, isToolUIPart, type UIMessage } from "ai";
import type { ToolStep } from "@/components/chat/ToolActivityDisclosure";

/** What a message renders, in stream order. Consecutive tool/data parts merge into one card. */
export type Segment =
  | { kind: "text"; text: string; key: string }
  | { kind: "reasoning"; text: string; key: string }
  | { kind: "tools"; steps: ToolStep[]; callIds: string[]; key: string };

/** Agent display names by registry key and id, for "agent-<key>" delegation tools. */
export type AgentNames = Record<string, string>;

/** Client-observed tool timing (the stream carries none): first seen → first finished. */
const toolTimes = new Map<string, { start: number; end?: number }>();

export function messageSegments(message: UIMessage, agentNames: AgentNames): Segment[] {
  const segments: Segment[] = [];
  message.parts.forEach((part, index) => {
    const key = `${message.id}:${index}`;
    if (isTextUIPart(part)) {
      if (part.text.trim()) segments.push({ kind: "text", text: part.text, key });
      return;
    }
    if (isReasoningUIPart(part)) {
      if (part.text.trim()) segments.push({ kind: "reasoning", text: part.text, key });
      return;
    }
    let step: { step: ToolStep; callId: string } | null = null;
    if (isToolUIPart(part)) {
      const status =
        part.state === "output-error" || part.state === "output-denied"
          ? "error"
          : part.state === "output-available"
            ? "done"
            : "running";
      step = { step: { label: toolLabel(getToolName(part), agentNames), count: 1, status }, callId: part.toolCallId };
      track(part.toolCallId, status !== "running");
    } else if (isDataUIPart(part) && part.type.startsWith("data-tool-agent")) {
      // Mastra sub-agent progress parts; shape varies, so only a safe label is shown.
      const data = (part.data ?? {}) as Record<string, unknown>;
      const name = typeof data.name === "string" ? data.name : typeof data.agentName === "string" ? data.agentName : null;
      step = { step: { label: name ? `${name} working` : "Sub-agent step", count: 1, status: "done" }, callId: key };
    }
    if (!step) return; // step-start, sources, files and unknown parts render nothing.
    const last = segments.at(-1);
    if (last?.kind === "tools") {
      last.steps.push(step.step);
      last.callIds.push(step.callId);
    } else {
      segments.push({ kind: "tools", steps: [step.step], callIds: [step.callId], key });
    }
  });
  return segments;
}

function track(callId: string, finished: boolean) {
  const now = Date.now();
  const time = toolTimes.get(callId) ?? { start: now };
  if (finished && time.end === undefined) time.end = now;
  toolTimes.set(callId, time);
}

/** Wall time across a card's tool calls, when all of them were watched finishing. */
export function toolsDurationMs(callIds: string[]): number | undefined {
  const times = callIds.map((id) => toolTimes.get(id));
  if (times.some((t) => !t || t.end === undefined)) return undefined;
  const start = Math.min(...times.map((t) => t!.start));
  const end = Math.max(...times.map((t) => t!.end!));
  return end - start;
}

/** "agent-cfoAgent" → "Delegated to CFO Agent"; "crustdataCompanyEnrich" → "Crustdata company enrich". */
export function toolLabel(toolName: string, agentNames: AgentNames): string {
  if (toolName.startsWith("agent-")) {
    const key = toolName.slice("agent-".length);
    return `Delegated to ${agentNames[key] ?? humanize(key)}`;
  }
  return humanize(toolName);
}

function humanize(name: string): string {
  const words = name
    .replace(/[-_]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .trim()
    .toLowerCase();
  return words.charAt(0).toUpperCase() + words.slice(1);
}

/** Plain text of a message, for previews and copy. */
export function messageText(message: UIMessage): string {
  return message.parts
    .filter(isTextUIPart)
    .map((part) => part.text)
    .join("\n")
    .trim();
}
