import { resolve } from "node:path";
import { Mastra } from "@mastra/core/mastra";
import { LibSQLStore } from "@mastra/libsql";
import { dataDir } from "../data-dir";
import "../telemetry";
import { assistant } from "./agents/assistant";
import { marketResearcher } from "./agents/market-researcher";
import { cfoAgent } from "./agents/cfo";
import { githubAgent } from "./agents/github";

export const mastra = new Mastra({
  storage: new LibSQLStore({ id: "mastra", url: `file:${resolve(dataDir(), "mastra.db")}` }),
  agents: { assistant, marketResearcher, cfoAgent, githubAgent },
});

import { Agent } from "@mastra/core/agent";
import { memory } from "../memory";
import { wrapMastra } from "neatlogs/mastra";
import { ASSISTANT_INSTRUCTIONS } from "../prompts";
import { marketResearcher } from "./market-researcher";
import { cfoAgent } from "./cfo";
import { githubAgent } from "./github";

export const assistant = wrapMastra(new Agent({
  id: "assistant",
  name: "Assistant",
  description: "Primary assistant that handles conversations and coordinates specialist agents.",
  instructions: ASSISTANT_INSTRUCTIONS,
  model: "deepseek/deepseek-flash",
  memory,
  agents: { marketResearcher, cfoAgent, githubAgent },
  defaultOptions: {
    maxSteps: 6,
    delegation: {
      onDelegationStart: () => ({ modifiedMaxSteps: 12 }),
    },
  },
}));
import { Chat } from "chat";
import { toAiMessages } from "chat/ai";
import { createWhatsAppAdapter } from "@chat-adapter/whatsapp";
import { createMemoryState } from "@chat-adapter/state-memory";
import { mastra } from "../mastra";
import { log, trace } from "neatlogs";
import { conversationSessionId, traceRequest } from "../telemetry";

export const bot = new Chat({
  userName: "whatsapp",
  adapters: {
    whatsapp: createWhatsAppAdapter(),
  },
  state: createMemoryState(),
  // The memory state adapter accepts Infinity to disable count-based trimming.
  history: { thread: { maxMessages: Number.POSITIVE_INFINITY } },
  concurrency: {
    strategy: "burst",
    debounceMs: 1000,
    maxQueueSize: 20,
    queueEntryTtlMs: 10 * 60 * 1000,
  },
});

bot.onDirectMessage(async (thread) => {
  const started = Date.now();
  try {
    await traceRequest("whatsapp", conversationSessionId(thread.id), async () => {
      let conversation: Awaited<ReturnType<typeof toAiMessages>> = [];
      await trace({ name: "whatsapp.history", kind: "RETRIEVER" }, async (activeSpan) => {
        const { messages } = await bot.history.thread.list(thread.id);
        conversation = await toAiMessages(messages);
        const historyBytes = Buffer.byteLength(JSON.stringify(conversation), "utf8");
        activeSpan.setAttribute("app.history.messages", conversation.length);
        activeSpan.setAttribute("app.history.bytes", historyBytes);
        log("History loaded", { messages: conversation.length, historyBytes });
        return { messages: conversation.length, historyBytes };
      });
      if (!conversation.length) return;
      console.info("WhatsApp assistant started", { messages: conversation.length });
      // Typing is best-effort and does not add progress messages to chat history.
      await thread.startTyping().catch((error: unknown) => {
        console.error("WhatsApp typing indicator failed", error);
      });
      const agent = mastra.getAgent("assistant");
      const response = await agent.generate(conversation);
      if (!response.text.trim()) throw new Error("Assistant returned an empty response");
      await trace({ name: "whatsapp.reply", kind: "TOOL" }, async () => {
        await thread.post(response.text);
        return { sent: true };
      });
      console.info("WhatsApp reply sent", { durationMs: Date.now() - started });
      return response.text;
    });
  } catch (error: unknown) {
    console.error("WhatsApp conversation failed", error);
    await thread.post("Sorry, I couldn't complete that request. Please try again.").catch((replyError: unknown) => {
      console.error("WhatsApp error reply failed", replyError);
    });
  }
});
import type { ServerResponse } from "node:http";
import type { Role } from "./index";
import type { SessionUser } from "./session";

export type AgentAccess = "all" | "admin";

// Keyed by Mastra agent id. To make a future agent admin-only, add its id here as "admin".
const agentAccess: Record<string, AgentAccess> = {
  assistant: "all",
  "market-researcher": "all",
  cfo: "all",
  github: "all",
};

// Admins can use every agent; everyone else only agents marked "all" (unlisted agents default to "all").
export function canUseAgent(user: SessionUser, agentId: string): boolean {
  if (user.role === "admin") return true;
  return (agentAccess[agentId] ?? "all") === "all";
}

// Guard for admin-only routes: sends 403 and returns false when the user lacks the role (admin satisfies any role).
// Responds inline (not via chat-api's sendJson) to keep the auth module free of mastra imports.
export function requireRole(user: SessionUser, res: ServerResponse, role: Role): boolean {
  if (user.role === "admin" || user.role === role) return true;
  res.writeHead(403, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify({ error: "Forbidden" }));
  return false;
}
import { Chat } from "@ai-sdk/react";
import { DefaultChatTransport, type UIMessage } from "ai";
import { handleUnauthorized, onSessionReset } from "@/lib/auth";

/**
 * One AI SDK `Chat` per agent, kept for the whole session. useChat({ chat }) renders whichever
 * is open; because the state lives in the Chat instance (not the component), history survives
 * switching agents and a reply keeps streaming in the background. The sidebar subscribes to
 * every chat through the same store.
 */

const chats = new Map<string, Chat<UIMessage>>();
const listeners = new Set<() => void>();
const unread = new Set<string>();
/** Client-side receive time per message id (the stream carries no timestamps). */
const stamps = new Map<string, number>();
/** Agents whose saved history is still being fetched; sending waits for it. */
const loading = new Set<string>();
/** Last history load/clear failure per agent, shown like any other chat error. */
const historyErrors = new Map<string, Error>();
const clearing = new Set<string>();
/** Bumped by resetChats so a history response for a previous user is dropped. */
let epoch = 0;
let version = 0;
let activeKey: string | null = null;

function notify() {
  version += 1;
  for (const listener of listeners) listener();
}

function stampAll(chat: Chat<UIMessage>) {
  for (const message of chat.messages) {
    if (stamps.has(message.id)) continue;
    const created = (message.metadata as { createdAt?: string | number } | undefined)?.createdAt;
    const at = created ? new Date(created).getTime() : Number.NaN;
    stamps.set(message.id, Number.isNaN(at) ? Date.now() : at);
  }
}

export function getChat(agentKey: string): Chat<UIMessage> {
  let chat = chats.get(agentKey);
  if (chat) return chat;
  chat = new Chat<UIMessage>({
    id: agentKey,
    transport: new DefaultChatTransport({
      api: `/api/chat/${encodeURIComponent(agentKey)}`,
      // Same response goes back to useChat (its error flow is unchanged); a 401 also ends the session.
      // History lives server-side (Mastra Memory), so only the newest message is sent.
      prepareSendMessagesRequest: ({ messages, body }) => ({ body: { ...body, message: messages.at(-1) } }),
      fetch: async (input, init) => {
        const res = await fetch(input, init);
        if (res.status === 401) handleUnauthorized();
        return res;
      },
    }),
    onFinish: ({ isAbort, isError }) => {
      if (!isAbort && !isError && activeKey !== agentKey) {
        unread.add(agentKey);
        notify();
      }
    },
  });
  const created = chat;
  created["~registerMessagesCallback"](() => {
    stampAll(created);
    notify();
  }, 120);
  created["~registerStatusCallback"](notify);
  created["~registerErrorCallback"](notify);
  chats.set(agentKey, created);
  void loadHistory(agentKey, created);
  return created;
}

const historyUrl = (agentKey: string) => `/api/chat/${encodeURIComponent(agentKey)}/history`;

/** Seeds the Chat from the saved thread. Resolves before anything can be sent (the composer waits on `loading`). */
async function loadHistory(agentKey: string, chat: Chat<UIMessage>) {
  const mine = epoch;
  loading.add(agentKey);
  historyErrors.delete(agentKey);
  notify();
  try {
    const res = await fetch(historyUrl(agentKey));
    if (mine !== epoch) return;
    if (res.status === 401) {
      handleUnauthorized();
      return;
    }
    if (!res.ok) throw new Error(`Couldn't load the conversation (${res.status}).`);
    const data = (await res.json()) as { messages?: UIMessage[] };
    if (mine === epoch && chat.messages.length === 0 && Array.isArray(data.messages)) {
      chat.messages = data.messages;
    }
  } catch (error) {
    if (mine === epoch) historyErrors.set(agentKey, error instanceof Error ? error : new Error(String(error)));
  } finally {
    if (mine === epoch) {
      loading.delete(agentKey);
      notify();
    }
  }
}

export function isHistoryLoading(agentKey: string): boolean {
  return loading.has(agentKey);
}

export function historyError(agentKey: string): Error | undefined {
  return historyErrors.get(agentKey);
}

export function dismissHistoryError(agentKey: string) {
  if (historyErrors.delete(agentKey)) notify();
}

export function retryHistory(agentKey: string) {
  const chat = chats.get(agentKey);
  if (chat) void loadHistory(agentKey, chat);
}

/** New chat: delete the saved thread first; on failure keep the messages and surface the error. */
export async function clearChatHistory(agentKey: string) {
  if (clearing.has(agentKey)) return;
  const chat = getChat(agentKey);
  const mine = epoch;
  clearing.add(agentKey);
  void chat.stop();
  chat.clearError();
  historyErrors.delete(agentKey);
  try {
    const res = await fetch(historyUrl(agentKey), { method: "DELETE" });
    if (mine !== epoch) return;
    if (res.status === 401) {
      handleUnauthorized();
      return;
    }
    if (!res.ok) throw new Error(`Couldn't clear the conversation (${res.status}).`);
